import fnmatch, json, sys

def touched(index, files, repo="fcp"):
    lines = []
    for page in index:
        for glob in page["applies_to"]:
            if not glob.startswith(repo + ":"):
                continue
            hits = fnmatch.filter(files, glob[len(repo) + 1:])
            if hits:
                lines.append(f"- `{page['path']}` ({page['owner']}): matches `{hits[0]}`")
                break
    return ["These brain pages describe code this PR changes. Check them, or ask the owner:"] + lines if lines else []

index = json.load(open(sys.argv[1]))
files = [l.strip() for l in open(sys.argv[2]) if l.strip()]
print("\n".join(touched(index, files)))
